internal object DuaMniDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_breaking_fast" to DuaText("য়াম্না থুনা ৱাকৎলকপা", "পাম্বিদু মাঙখ্রে, শিরোইশিং অদু নুংশিনখ্রে, অমসুং অল্লাহনা পাম্লবদি মনা অদু ফংলে।", "ইফ্তারগী মতমদদি।", "মসি মহাক্কী লাইরেম্বী সল্লল্লাহু অলৈহি ঵সল্লমনা মহাক্কী লাইরেম্বী কায়দনা হায়রি।"),
        "dua_new_clothes" to DuaText("অনৌবা পেজশিং হাপচিনবা", "হে অল্লাহ, থাগৎলিবসি পুম্নমক মসিনি; মসি ঐনা লৈতেংই। মসিগী অফবা অমদি মসিগী কান্নবশিং অদু ঐহাক্না পামজৈ, অদুগা মসিগী ফত্তবা অমদি ফত্তবা অদু মসিগী শেম্বনি হায়বগী মতাংদা ঐহাক্না তুম্বু শরণ পীজরি।", "অনৌবা ফিরোল অমা শিজিন্নবা মতমদা (শর্ট নত্ত্রগা তর্বনগুম্বা মমিং থোনখিবা)।", "মসি নবী সল্লল্লাহু অলৈহি ঵স্লমনা অনৌবা ফি-রোল অমা লৌরগা শেম্বা দোৱা অমনি। (নুংতিগী ওইবা দোৱা অসি'লৈতেংবা'গী মখাদা শেম্মি।)"),
        "dua_rabbana_atina" to DuaText("মালেম অসিদা অমসুং মসিগী তুংদা লৈরিবা অসিদা", "হে ঐখোয়গী ঈপূরোই, মালেম অসিদা ঐখোয়না অফবা অমসুং মাংজিল থোক্ত্রবদা ঐখোয়না অফবা ওইহনবিয়ু, অমসুং ঐখোয়না মৈগী অৱাবদগী ঙাকথোক্কদবনি।", "দি দুআ দি প্রোফেট সলিহ আলীহ ওস্লম্না অয়াম্বা মতমদা শেম্মি।", "মালেম অসিগী অমসুং অকোনবগী অফবা পুম্নমক খোমজিল্লিবা দুআ অমা।"),
        "dua_rabbi_zidni_ilma" to DuaText("লৌশিং হেনগৎহনবা", "হে ঐগী লাইরেম্বী, ঐহাক লৌশিং লৈরিবসি হেনগৎহনবা।", "লৌশিং হেনগৎনবা হোৎনবা।", "আল্লাহনা প্রোফেট সলিহ আলীহ ওস্লমদা লৌশিং নত্তনা অতৈ অমত্তদা হেনগৎনবা হায়নবা য়াথং পীখি।"),
        "dua_musa_sharh_sadr" to DuaText("চেস্ত ওন তৌবা (মুসা AS)", "হে ঐগী ইশ্বর, ঐগীদমক ঐগী ছাতী অসি চাওথোকউ, ঐগী থবক অদু লায়থোকউ, অমসুং মখোয়না ঐগী ৱা ঙাংবদা খঙনবগীদমক ঐগী জিবা অসিদগী নোত অদু লৌথোকউ।", "চাংয়েং অমগী মমাংদা, ৱা ঙাংবগী নত্ত্রগা অরুবা থবক অমা।", "প্রফেট মুসা (এ. এস.) গী দুআ-নুংশিৎকী শান্তি অমসুং থবক তৌবদা লায়না।"),
        "dua_la_tuzigh" to DuaText("হৃদয় হৃদয় হৃদয়", "হে ঐখোয়গী ঈপূরে, অদোম্না ঐখোয়দা থৌশিল পীবা মতুংদা ঐখোয়গী থৱায়শিংবু হোংহল্লোইদবনি, অমসুং মশামক্তগী ঐখোয়দা থৌজাল পীবা ঙমহল্লোই। তশেংনমক্কী, অদোম্না খ্বাইদগী হেন্না কান্নবা পীবনি।", "লাই য়েকপা লাইয়েংগীদমক।", "থাজবা থম্নবা হোৎনরিবা মীওই অদু।"),
        "dua_ya_muqallib" to DuaText("ও টার্নর ওফ হার্টস", "হে হৃদয়ের টর্নর, আপনার ধর্মের প্রতি আমার হৃদয়কে দৃঢ় রাখুন।", "মসি লাইরেম্বী সল্লল্লাহু অলৈহি ঵সল্লমনা অয়াম্বা মতমদা তৌনরম্মি।", "উম্ম সলামাহ (রা.) গী মতুং ইন্না, দুআ অসি প্রোপেৎ সলিহ আলীহ ওস্লম্না অয়াম্বা মতমদা তৌখি।"),
        "dua_la_tuakhidhna" to DuaText("সুরাহ অল-বকরাহের শেষ ভার্সিস", "হে ঐখোয়গী ঈপূরে, ঐখোয়না মাংখ্রবদি নৎত্রগা করিগুম্বা তৌখ্রবদি ঐখোয়না থৌজাল লৌদে। হে ঐখোয়গী ঈপূরে, ঐখোয়গী মমাংদা লৈরম্বা মীওইশিংদা তৌখ্রব চুমথোকপগুম্না ঐখোয়গী মীদা তৌরোইদবনি। হে ঐখোয়গী ঈপূরে, ঐখোয়না লৌশিনবা ঙমদবা চুমথোকউ। ঐখোযনা মাংহন্দবা, ঐখোযনা মাংহন্দবা অমসুং ঐখোযনা থৌগল তৌ। ঐখোযনা ঐখোয়গী ঙাকশেল তৌবা, মরম অদুনা ঐখোয়না তৌগদব মীশিংদগী ঙাকথোক্নবা হোৎন।", "নুংশা শুদ্রিঙৈগী মমাংদা-সুরাহ অল-বকরাহগী অরোইবা ৱাহৈ পরেং অনি।", "করিগুম্বা কনাগুম্বা অমনা সুরাহ অল-বকরাহগী অরোইবা ৱাহৈ অনী অদু নুমিদাংৱাইরমদা ইখ্রবদি, মখোয়সি মহাকপু মতীকগনি।"),
        "dua_visiting_sick" to DuaText("অসুস্থতাকে দেখা", "ঐহাক্না শক্তি লৈরবা, শক্তি লৈরবা সিংহাসনগী মপু ওইরিবা, ঈশ্বরবু মহাকপু ফগৎনবা হায়জরি।", "অঙাং অদুদা চয়োল তরেৎকী মতুংদা ইনগদবা", "করিগুম্বা শিরবগী মতম লাকদ্রবদি, অল্লাহনা মহাকপু ফগৎহনগনি।"),
        "dua_ruqyah_pain" to DuaText("হকচাংগী অরুম্বা", "ঐহাক্না ঈশ্বরদা অমসুং মহাক্কী শক্তিদা ঐনা থেংনরক্লিবা অমসুং ঐহাক্না পামদবা ফত্তবা অসিদগী ঙাকথোক্নবা হোৎনজৈ।", "মসি শোক্নিংলিব মফমদদি খুৎ অদু থাংগৎউ, বিস্মিল্লাহবু কয়ারক অহুম হায়য়ু, অদুগা মসিগী দুআ অসি তরেৎনি।", "মসি প্রোপেৎ সলিহ আলীহ ওসল্মনা উথমান ইবন অবিল -'আস (আর. এ.) দা অৱাবা পীনবগীদমক তাক্লম্মী।"),
        "dua_ruqyah_nabawi" to DuaText("রোগীদের জন্য প্রোপেটিক রুক্হিয়া", "হে মীওইবা খুন্নাইগী ইশ্বর, অল্লাহ! খুদোংথিবা অদু লৌথোকউ অমসুং লাইয়েংউ, মরমদি নীনি ফগৎহনবা ঙম্বা; নীয়না লাইয়েংবখক্তনা লাইয়েং অমত্তা লৈতে-লায়না অমত্তা মাংহন্দবা লাইয়েং।", "হকচাং শাজেল তৌরিবদুগী মথক্তা খুৎ থাদুনা।", "মসি মহাক্কী ইমুং মনুংদা লৈবা মীওইশিংদা চৎলুরবা মতমদা প্রধান মন্ত্রী শ্রী নরেন্দ্র মোদীনা হায়খি।"),
        "dua_kalimat_tammat" to DuaText("অশেংবা ৱাহৈদা পুকচেল শেংলবা মীরৈবাক মচা", "ঐহাক্না মহাক্না শেম্লম্বা ফত্তবা অসিদগী অল্লাহগী মপুং ফাবা ৱাহৈশিংদা পুকনিংলি।", "মফম অমদা নত্ত্রগা মফম অমদা লৈবা।", "মফম অমদা লৈদুনা মসি হায়রম্বসিনা মহাক্না থাদোক্ত্রিবা ফাওবা মহাক্কী মফমদা করিগুম্বা অকায়বা পীদে।"),
        "dua_evil_eye" to DuaText("অঙাংশিং ঙাক-শেনবা (ফত্তবা মীৎ)", "ঐহাক্না মখোয় অনিমক্তা ঈশ্বরগী অশেংবা ৱাহৈদা শয়তান অমসুং শা-ঙাগী শা-ঙা খুদিংমক অমসুং খুদোংথিবা থোকহনবা মীৎ খুদিংমকদগী ঙাক-শেনবা পামজৈ।", "মসি রসূলুল্লাহ (স) না হসন অমসুং হুসেন (রা) গী মফমদা ইখি।", "অঙাংশিংবু ফত্তবা মীৎ অমসুং খুদোংথীবদগী ঙাকথোক্নবা সুন্নহ দুআ (অঙাং অমগী'উ'উধুকা'হায়না হায়নবা)।"),
        "dua_seeing_afflicted" to DuaText("মীওই অমবু চাংয়েং তৌবদা থেংথরবা", "ময়ামবু থাগৎপসি মহাক্না অদোম্না চাংয়েং তৌখিবদগী ঐ ঙাকথোক্লম্বা অমসুং মহাক্কী শেম্লকপগী অয়াম্বা শরুক অদুগী মথক্তা ঐবু থৌজাল পীবা অল্লাহনি।", "মীওই অমবু চাংয়েং তৌবদা (মশামকসু ৱা ঙাংবা)।", "মদুবু চাংয়েংদুগী মনুংদগী ঙাকথোক্নবগীদমক হোৎনরিবা মীওই অদুনা।"),
        "dua_istikhara" to DuaText("সালাত অল-ইস্তিকারা", "হে অল্লাহ, ঐহাক্না মাগী লৌশিং তম্না অফবা অমা ফংলি, ঐহাক্না মাগী শক্তি তম্না তৌবা ঙম্বা ফংলি, অমসুং ঐহাক্না মাগী অচৌবা থৌজাল অদু মাগী মফমদা হংলি। মাগী শক্তি লৈ অমসুং ঐগী শক্তি লৈতে। অদোম্না খঙলে অমসুং ঐহাক্না খঙবা ঙমদে, অমসুং অদোম্না উবা ঙমদবা অদু খঙবা মীওইনি। হে অল্লাহ, করিগুম্বা মসি (মসি খঙদনা) ঐগী ধর্ম, ঐগী পুন্সি অমসুং ঐগী লোইরকপদা অফবা ওইরবদি, ঐ পাম্বিয়ু, মসি ঐগীদমক লায়থোকউ অমসুং মসিদা ঐহাক্না থৌজাল পীবাউ। করিগুম্বা মসি ঐগী ধর্ম, ঐগী পুন্সি অমসুং ঐগী লোইরকপদা ফত্তবা ওইরবদি, ঐদগী মদু লৌথোকউ অমসুং মসিদগী ঐখোমদা হনজিনবাউ, অমসুং মসি ওইরক্কদবদু ঐগীদমক অফবা অমা য়াথংউ।", "লাই খোইরম্বদা খ্বাইদগী ফবা অমা থিবদা, লাই খোইরম্বদা খ্বাইদগী ফবা অমা লৈবগী রাক'আহ অনিগী মতুংদা।", "মহাক্না কুরানগী সুরাহ অমা তমদুনা কম্পেনিয়নশিংদা হিরম খুদিংমক্তা ইস্তিকারা তাক্লম্মি।"),
        "dua_allahumma_bika_asbahna" to DuaText("আল্লাহুম্মা বীকা আসবাহনা", "হে অল্লাহ, ঐখোয়না অয়ুক পুংদা চংলি অমসুং নুংশা নুংশা চংলি; ঐখোয়না নুংশা ফাওরগা হিংই অমসুং নুংশা ফাওরগা হিংই, অমসুং নুংশা ফাওরগা অমুক হন্না হল্লকপা অসিনি।", "মদু ইং 1982 গী অঙনবা মতনি।", "প্রধান মন্ত্রী শ্রী নরেন্দ্র মোদীগী হৌদোক ৱারোলদা প্রধান মন্ত্রী শ্রী নরেন্দ্র মোদীনা হায়খি মদুদি প্রধান মন্ত্রী শ্রী নরেন্দ্র মোদীনা ঙসি অয়ুক অমসুং নুমিদাংৱাইরমদা লৈবাক মীয়ামদা ৱা ঙাংগনি।"),
        "dua_allahumma_bika_amsayna" to DuaText("আল্লাহুম্মা বিকা আমসাইনা", "হে অল্লাহ, ঐখোয়না নুংথিলদা ঐখোয়না চঙই অমসুং নুংথিলদা ঐখোয়না চঙই; ঐখোয়না নুংথিলদা হিংই অমসুং নুংথিলদা ঐখোয়না শিরই, অমসুং মসি তুংলমদুনা হল্লকই, অমসুং মসি তুংলমদুনা হল্লকপা অসিনি।", "মদু ইং 1982 গী অঙনবা মতনি।", "প্রধান মন্ত্রী শ্রী নরেন্দ্র মোদীগী হৌদোক ৱারোলদা প্রধান মন্ত্রী শ্রী নরেন্দ্র মোদীনা হায়খি মদুদি প্রধান মন্ত্রী শ্রী নরেন্দ্র মোদীনা ঙসি অয়ুক অমসুং নুমিদাংৱাইরমদা লৈবাক মীয়ামদা ৱা ঙাংগনি।"),
        "dua_afiyah_morning" to DuaText("আফিয়া শেখ হাসিনা", "হে আল্লাহ, ঐহাক্না মালেম অসিদা অমসুং তুংদা লৈরিবা অসিদা থৌজাল অমসুং য়াইফনবা হায়জরি।", "প্রধান মন্ত্রী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী", "অফবা হায়বদুদগী হেন্না ফববু কদাইদগী কোৎলুদগে।"),
        "dua_afini_fi_badani" to DuaText("হকচাংগী অরুম্বা, হকচাংগী অরুম্বা অমসুং হকচাংগী অরুম্বা", "হে অল্লাহ, ঐগী হকচাংগী হকচাংবু ফজবিয়ু। হে অল্লাহ, ঐগী খোঞ্জেলবু ফজবিয়ু। হে অল্লাহ, ঐগী মীৎবু ফজবিয়ু। নুংশিবা নত্তনা লাইরেম্বী অমত্তা লৈতে।", "নুমিৎ খুদিংগী অয়ুক অমসুং অয়ুক পুং 3দা হৌগৎলু।", "হকচাং ফনবা অমসুং সেন্সশিংবু ঙাক শেনবা দুআ অমা।"),
        "dua_ya_hayyu_aslih" to DuaText("ঐগী ৱাফম পুম্নমক অমুক হন্না শাদুনা থম।", "হে মতম চুপ্পদা হিংবা ঙম্বা, হে সস্তেনর, ঐহাক্না মাগী থৌজালনা মতেং পাংইঃ ঐগী থবক পুম্নমক অমুক হন্না তৌ অদুগা ঐনা মমিৎ চিংবা ফাওবা ঐখোযনা থাদোক্তবা য়াদে।", "মসি অয়ুক অমসুং নুংথিলগী মতমদা হায়রক্নবা প্রোফেত সলিহ আলীহ ওসল্মনা ফাতিমাহ (রা.) দা পাউতাক পীখি।", "হীরম খুদিংমক্তা অল্লাহ্না মতেং পাংনবা হোৎনৌ।"),
        "dua_subhanallah_adada_khalqihi" to DuaText("জুৱাইরিহ (আর. এ.) গী তাসবিহ", "ঈশ্বরবু ইকায় খুম্নজরি অমসুং থাগৎলিবসি মহাক্কীনি-মহাক্কী শেম্লকপা, মহাকপু পামজবগুম্না, মহাক্কী সিংহাসনগী অরুম্বা অমসুং মহাক্কী ৱাহৈশিংগী শংবান্গা মান্ননা।", "অয়ুক পুং অহুম-ধিকরগী পুংশিংদগী হেন্না অরুম্বা।", "ৱাহৈ পরেং মরি অসি অহৌবা নুমিত্তগী অয়ুক ফাওবফাউবা অহৌবা নুমিত্তগী অহৌবা ফাওবা তিনশিনবা হায়বসি দিখরদগী হেন্না ৱাংই।"),
        "dua_salawat" to DuaText("দুরোদ-ই-ইব্রাহিমি", "হে অল্লাহ, মুহম্মদ সলিহ আলীহ ওসলিম অমসুং মুহাম্মদকী ইমুং মনুংদা লাই খোইরম্বা পাউদুদুদু অদোম্না ইব্রাহিম (এ. এস.) অমসুং ইব্রাহিমগী ইমুং মনুংদা লাই খোইরম্বা মতমদা; অদোম্না থাগৎনিংঙাই ওইরবা, ইকায় খুম্ননিংঙাই ওইরবা। হে অল্লাহ, মুহাম্মদ সলিহ আলীহ ওসলিম অমসুং মুহাম্মদকী ইমুং মনুংবু থৌগল তৌবীদুনা অদোম্না ইব্রাহিম (এ. এস.) অমসুং ইব্রাহিমগী ইমুং মনুংবু থৌগল তৌবীদুনা থৌগল তৌবীদুনা; অদোম্না থাগৎনিংঙাই ওইরবা, চাওথোকচনিংঙাই ওইরবা।", "সলৱাত ওন দি প্রোফেট সলিহ আলীহ ওস্লম লাই খোইরম্বদা অমসুং মতম পুম্বদা।", "করিগুম্বা সালৱাত অমা অমা থাবদা, অল্লাহনা মহাক্কী মফমদা থৌজাল তরাই অমা থম্মী (মুস্লিম 408)।"),
        "dua_wudu_after" to DuaText("ওয়াদু পরে", "ঐহাক্না চুম্মী মদুদি অল্লাহ নত্তনা, অমত্তা ওইনা, শুপ্নতগী, কনাগুম্বা অমত্তনা লাই খোইদারকপগী হক লৈতে, অমসুং মুহাম্মাদ সলিহ আলীহ ওস্লম অসি মহাক্কী থৌমী অমসুং রসূলনি। হে অল্লাহ, ঐহাক্না তৌগেবু তৌগেবু তৌগেবু তৌগেবু তৌগেবু তৌগে।", "ৱুদু লোইরবা মতুংদা।", "স্বর্গগী থোঙনাও 8 অসি মহাক্না পাম্লিবা মীওই অমহেক্তনা চংনবগীদমক হাংদোকই।"),
        "dua_wudu_before" to DuaText("ওয়াদু আগে", "মসি ঈশ্বরগী মমিংনি।", "ওয়াদু শুরু করার সময়।", "মসিদা অল্লাহগী মমিং য়াওদবা মীওই অমগী (মপুং ফাবা) ৱুদু লৈতে।"),
        "dua_istiftah" to DuaText("ওপনিং প্লেলিকেশন (সানা)", "হে অল্লাহ, মসি নিংথিনা চাওথোকচনিংঙাইনি অমসুং মসি নিংথিনা চাওথোকচনিংঙাইনি। মসি নিংথিনা চাওথোকচনিংঙাইনি, মসি নিংথিনা চাওথোকচনিংঙাইনি অমসুং মসি নত্তনা লাইরেম্বী অমত্তা লৈতে।", "লাই খোইরম্বদা, তাকবীর হাংদোক্লবা হেক মতুংদা।", "নামাজের দুয়া খোলার সুন্নাহ।"),
        "dua_ruku" to DuaText("ইন রুক্", "লাইরেম্বীনা খোইদারমই, নীংতম্বা লাইরেম্বীনা খোইদারমই।", "চুমা শুবা মীওই অহুম মখাতানা শিখ্রবনি।", "সুন্নাহ তাসবিহ, রুকু"),
        "dua_sujood" to DuaText("সুজুদা", "খ্বাইদগী ৱাংবা, খ্বাইদগী ৱাংবা, ঐগী লাইবুংদা ইকায় খুম্নবা উৎচরি।", "চুজুদতা য়ামদ্রবদা অহুম মখায় হৌবা।", "লাই খুবা মতমদা থবক শুবা মীওই অদু মহাক্কী লোর্দকা খ্বাইদগী নকশিন্নৈ (মুস্লিম 482)।"),
        "dua_rising_ruku" to DuaText("রিক্যুদগী হৌরকপা", "আল্লাহনা মহাকপু থাগৎলিবা মীওই অদু তাবা ঙমই। হে ঐখোয়গী ঈপূরে, ময়ামবু থাগৎপসি উমংনি।", "রুকুদগী ৱাংখৎলকপা অমসুং থোংনাও ওইনা লৈদুনা।", "'রব্বানা ৱা লাকাল-হমদ'অসি মীরোল্লিবা নুপিশিংগী অদুগা চূনবা মীওই অমগী মমাংদা তৌখ্রবা পাপশিং অদু মাংখিগনি।"),
        "dua_between_sajdas" to DuaText("সাজদাস দু'য়ের মধ্যে", "হে ঐগী নুংশিরবা খুঙ্গং, ঐঙোন্দা ইকুবোক য়াম্না চাওবি।", "প্রোস্ত্রেসন অনিগী মরক্তা লৈবা মতমদা।", "প্রোস্ত্রেসনগী মরক্তা লৈবা সুন্নহ দুআ।"),
        "dua_before_salam_four" to DuaText("পোৎ মরিদগী রিফুজ তৌবা (সলামগী মমাংদা)", "হে আল্লাহ, ঐহাক্না নরক্কী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাইয়েংগী লাই", "অরোইবা তাশাহুদ অমসুং সালৱৎকী মতুংদা, সালমগী মমাংদা।", "প্রধান মন্ত্রী মোদীগী হৌদোক ৱারোলদা প্রধান মন্ত্রী মোদীনা হায়খি মদুদি প্রধান মন্ত্রী মোদীনা লৈবাক মীয়ামদা য়াইফ-পাওজেল পীনবা পান্দম থম্লদুনা লৈবাক মীয়ামদা য়াইফ-পাওজেল পীনবা পান্দম থম্লম্বনি।"),
        "dua_qunoot_witr" to DuaText("কুনুত ইন উইতর", "হে অল্লাহ, অদোম্না থৌশিল পীবা মীওইশিংগী মরক্তা ঐঙোন্দা থৌশিল পীবা, অদোম্না থৌশিল পীবা মীওইশিংগী মরক্তা ঐহাক্না অফবা ওইহনবী, অদোম্না থৌশিল পীবা মীওইশিংগী মরক্তা ঐহাক্না থৌশিল পীবা, অদোম্না পীবা মীশিংদা ঐহাক্না থৌশিল পীবা, অদোম্না পীবা মীশিংদা ঐহাক্না থৌজাল পীবা, অমসুং অদোম্না পীবা মীওৎ-মীনৈদগী ঐহাক্না ঙাকপা। অদোম্না য়াথং পীবা অমসুং অদোম্না শৌগৎপা মীওই অমত্তনা থৌজাল পীবা ঙমদে, অমসুং অদোম্না মরুপ ওইবগী মীওই অদু মাঙজৌননা তৌদে। ঐখোয়গী প্রভূ, অদোম্না থৌজাল পীবা অমসুং ইকায় খুম্নজবা ওইবীগনু।", "ৱিতর লাইশোনদা-প্রোফেট সলিহ আলীহ উস্লমনা মসি হসন ইবন অলি (আর. এ.) দা তাক্লম্মী।", "ৱিতরগী সুন্নাহ কুনুত (হানাফিসশিংগী মরক্তা,'অল্লাহুম্মা ইন্না নস্তাইনুকা'অসিসু ময়াম্না খঙনরে।)"),
        "dua_qunoot_hanafi" to DuaText("কুনুত (আল্লাহুম্মা ইন্না নস্তাইনুকা)", "হে অল্লাহ, ঐখোয়না মাগী মতেং অমসুং থৌজাল লৌরে, ঐখোয়না নিন্নু থাজবা থম্লি অমসুং ঐখোয়না নিন্নু থাজবা থম্লি, ঐখোয়না খ্বাইদগী ফবা মওংদা নোংখৌ থাগৎলি, ঐখোয়না তৌববু থাগৎলি অমসুং তৌজবা লৈতে, অমসুং ঐখোয়না করিগুম্বা কনাগুম্বা অমনা তৌদবনা তৌগদবদু থাদোকই। হে অল্লাহ, ঐখোয়না অমত্তা ওইনা ঐখোয়না পুকনিংই, ঐখোয়না খোইদারমই অমসুং সিজদা তৌই, ঐখোয়না খোঙজেল য়াৎলি অমসুং হোৎনই, ঐখোয়না মাগী থৌজাল ফংজনি অমসুং ঐখোয়না মাগী থৌজাল ফংজনি অমসুং ঐখোয়না মাগী থৌজাল ফংজনি। ঐখোয়না তশেংনা মাগী থৌজাল অদু থাজদবা মীওইশিংদা য়ৌহনগনি।", "ইন ৱিটর-দি প্রেক্তিস ওফ দি হানাফিস।", "কুনুততা উমর (আর. এ.) দগী পাউদমখি।"),
        "dua_sleep_aslamtu" to DuaText("নুংশিনবা ঙাংগনিঙৈগী অরোইবা ৱাহৈ", "হে অল্লাহ, ঐহাক্না ইশাবু তুম্বদা থাজৈ, ঐগী থবক অদু ঐহাক্না তুম্বদা থাজৈ, অমসুং ঐহাক্না তুম্বু ঙাক শেনবা হোৎনগনি, মসি নংগী থাজবা অমসুং নংগী ৱাখলদগীনি। নংখক্তনা নত্তনা পুকচেল শেংবা অমদি তানবা অমত্তা লৈতে। ঐহাক্না নংনা ফোংখিবা লাইরিক অসিদা অমসুং নংনা ফোংখিবা নাবীদা থাজবা থম্লি।", "ৱুদুগী মতুংদা, য়েৎ থংবা নাকলদা লৈ-শুম্বগী মমাংদা খ্বাইদগী অরোইবা ৱাহৈ।", "করিগুম্বা মহাক্না নুমিদাংদু শিদ্রবদি, মহাক্না ফিত্রাদা (ইসলাম) শিদ্রবনি।"),
        "dua_waking_night" to DuaText("নুমিদাংদু অসুম অসুম থেঙজিল্লক্লি।", "অচুম্বা লাইয়েংগী হক অসি অল্লাহ নত্তনা, অমত্তা ওইনা, শুপ্নতগী লৈজরক্তনা, কনাগুম্বা অমত্তদা লৈতে। মহাক্কী লৈঙাকসি মহাক্কীনি, মহাক্কী পুকচেল শেংবগী হকসু লৈ, অমসুং মহাক্কী শক্তি পুম্নমক মহাক্কীনি। পুকচেল শেংবসি অল্লাহ্না ওইরি, পুকচেল শেংবসি অল্লাহ্না ওইরি, অল্লাহ নত্তনা কনাগুম্বা অমত্তনা পুকচেল শেংবগী হক লৈতে, অল্লাহনা খ্বাইদগী চাউবা অমনি, অমসুং অল্লাহ নত্তনা শক্তি নত্ত্রগা শক্তি অমত্তা লৈতে। হে অল্লাহ, ঐঙোন্দা ক্ষমা তৌ।", "নুমিদাংদু ঐখোয় হোটেল অমদা লৈরে।", "মহাক্কী দুআগী পাউখুম পী, অমসুং করিগুম্বা মহাক্না ৱুডু তৌরবদি অমসুং লাই খোইদারবদি মহাক্কী লাই খোইদারমগনি।"),
        "dua_hamm_ibn_masud" to DuaText("দুয়া ফর গ্রিফ (ইবন মাস'উদ)", "হে অল্লাহ, ঐহাক্না মাগী থৌমীনি, মসি মাগী থৌমীগী মচানি, মসি মাগী থৌমীগী মচানি। ঐগী মমায় অসি মাগী খুৎদা লৈ, মসি ঐগী মীদা পীবা য়াথংনি, অমসুং মসি ঐগী মতাংদা পীবা ৱারেপ অদু অচুম্বানি। ঐহাক্না মাগী মমিং খুদিংমক হায়রগা হায়জরি, মসি মহাক্না মাগী মমিং থোনখিবনি, নত্ত্রগা মহাক্না লাইরিক অসিদা ফোঙদোকখিবনি, নত্ত্রগা মহাক্না শেম্বনি, নত্ত্রগা মহাক্না থেংনরকপশিংদু খঙবা ঙম্লি-মদুদি অদোম্না কুরান অসিবু ঐগী থৱায়গী স্প্রিং, ঐগী বুককী মঙাল, ঐগী অৱাবা অমসুং ঐগী চিংনবা মাঙহনলি।", "অৱাবা অমসুং অৱাবা-অল্লাহনা অৱাবা অদুবু নুংঙাইবগা মহুৎ শিন্দ্রে।", "আল্লাহনা মহাক্কী অৱাবা অমসুং অৱাবা অদু লৌথোকই অমসুং মহাক্কী মফমদা নুংঙাইবা পী।"),
        "dua_difficulty_sahl" to DuaText("করিগুম্বা মহাক অদু থকপা ঙম্লবদি,", "হে অল্লাহ, করিগুম্বা করিগুম্বা নংনা পাম্লিবা অদু নত্তনা অতোপ্পা অমত্তা লায়না নত্তে, অমসুং করিগুম্বা নংনা পাম্লিবা অদু হেন্না লায়থোকহল্লি।", "করিগুম্বা মহাক অদু থকপা ঙম্লবদি, মঙোন্দা হংনীংলকই।", "চাংয়েং তৌবদা থেংথরবা অমসুং অরুবা থবক কয়া অমা।"),
        "dua_musibah" to DuaText("অপোন এ কেলামিতী (ইস্তিরজা)", "ঐখোয়না অল্লাহগীনি অমসুং ঐখোয়না মহাক্কী মনাক্তা হল্লক্কনি। হে অল্লাহ, ঐগী অৱাবা মতমদা ঐনা মনা ফংহনবীরি অমসুং মদুগী মহুৎতা হেন্না ফবা অমা পী।", "করিগুম্বা অকিব নত্ত্রগা অকিবগী মতাংদদি।", "আল্লাহনা হেন্না ফবা অমা পীরগনি-উম্ম সলামাহ (রা) অসি প্রোফেত সলিহ আলীহ ওস্লম পীখি।"),
        "dua_debt" to DuaText("শেন্দোংগী চাংদগী ঙাকথোক্নবা", "হে অল্লাহ, অদোম্না আইন কায়দবা তৌখিবশিংগী মাইয়োক্তা আইন কায়দবা তৌখিবদু ঐগা মতীক চানা পীরগনি, অমসুং অদোম্না পীবা থৌজালনা ঐহাক্না ময়ামদগী নীংতম্বা পুরক্কনি।", "লোন লৌবগীদমক-অলি (আর. এ.) না তমজখিবা।", "করিগুম্বা শেন্দোং অসি চীংশাং অমা ওইরবসু, অল্লাহনা মদু লেপথোক্কনি।"),
        "dua_anger" to DuaText("অমনোযোগী শিক্ষার্থী", "ঐনা শাপিত শয়তানদগী অল্লাহদা শরণ লৈ।", "মদু লেপত্রিবফাউবা মতুংদা অমুক থোকহন্খি।", "মহাক্না হায়খি মদুদি করিগুম্বা মহাক্না অসুম্না হায়রম্লবদি মহাক্কী কোপ অদু মাঙখিগনি।"),
        "dua_waswasa" to DuaText("বিশ্বাসের বিরুদ্ধে ওয়াসাসা", "ঐহাক্না ঈশ্বর অমসুং মহাক্কী রসূলশিংদা থাজবা থম্লি।", "শয়তাননা থাজবগী মতাংদা ৱা ঙাংবা মতমদা লাকই।", "ৱা ঙাংবা অদু লাকপগা, মসি হায়য়ু অমসুং মদুদগী থেম্লু (অমসুং অল্লাহদা শরণ লৈয়ু)।"),
    )
}
